package vn.covie.inventory.application;
import java.util.*; import org.springframework.stereotype.Service; import vn.covie.inventory.model.InventoryBalanceEntity; import vn.covie.inventory.persistence.InventoryBalanceRepository;
@Service public class InventoryLockService { private final InventoryBalanceRepository balances; public InventoryLockService(InventoryBalanceRepository balances){this.balances=balances;} public List<InventoryBalanceEntity> lockTrackedBalances(Set<UUID> ids){List<UUID> sorted=ids.stream().filter(Objects::nonNull).distinct().sorted().toList();if(sorted.isEmpty())return List.of();List<InventoryBalanceEntity> found=balances.lockAllByLocationVariantIds(sorted);if(found.size()!=sorted.size()||found.stream().map(InventoryBalanceEntity::getLocationVariantId).distinct().count()!=sorted.size())throw new IllegalStateException("Missing tracked inventory balance");return found;} }
